// === Tab: sketch291393 ===
ArrayList<Particle> m; //let Particles themselves

let count = 200; //let many particles to spawn

let spdLimit = 200; //let limit of each particle's speed in pixels per second

let SUNSET = 1;
let ICE = 2;
let FIRE = 3;

let THEME = SUNSET;

function setup() {  
  createCanvas(1000, 750);
  colorMode(HSB, 360, 100, 100);
	THEME = 1+int(random(3));
  m = new ArrayList<Particle>();
  for (i = 0; i<count; i++) {
    m.add(new Particle());
  }
  window.simulatedMouseX = width/2;
  window.simulatedMouseY = height/2;
}

function draw() {
  noStroke();
  fill(0, 40);
  rect(-1, -1, width + 1, height + 1);
  fill(50, 50, 255);
  for (let a of m) {
    a.update();
    a.draw();
  }
}

class Particle {

  let prev, pos, mouse = new PVector(), spd, acc;
  col;
  let turnFactor = random(3, 10);

  constructor() {
    pos = new PVector(random(width), random(height));
    prev = new PVector(pos.x, pos.y);
    spd = new PVector(random(2), random(2));
    acc = new PVector();

    switch(THEME) {
        case SUNSET:
            col = color(random(320, 420) % 360, 90, 100);
            break;
        case ICE:
            col = color(random(155, 210), random(40, 100), 100);
            break;
        case FIRE:
            col = color(random(45), 90, 100);
            break;
        default:
            col = color(random(360), 90, 100);
            break;
    }

  }

  function update() {
    prev = new PVector(pos.x, pos.y);
    if (pos.x > width || pos.x < 0) {
      spd.x *= -0.9;
    }
    if (pos.y < 0 || pos.y > height ) {
      spd.y *= -0.9;
    }
    mouse.set((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
    let attraction = new PVector(mouse.x, mouse.y);
    attraction.sub(pos);
    acc.set(attraction);
    acc.normalize();
    acc.div(turnFactor);
    spd.add(acc);
    spd.limit(spdLimit * (1/60));
    pos.add(spd);
  }

  function draw() {
    stroke(col);
    strokeWeight(3);
    line(prev.x, prev.y, pos.x, pos.y);
  }
}

